solutionCode:
pub fn parse_percentage(input: &str) -> Result<u32, String> {
    let clean = input.trim().trim_end_matches('%').trim();
    let val: u32 = clean
        .parse()
        .map_err(|_| "Invalid number format".to_string())?;

    if val > 100 {
        return Err("Percentage cannot exceed 100".to_string());
    }

    Ok(val)
}

fn main() {
    println!("{:?}", parse_percentage("75%"));
    println!("{:?}", parse_percentage("120%"));
    println!("{:?}", parse_percentage("invalid"));
}

