solutionCode:
pub fn process_scores(scores: &[i32]) -> Vec<i32> {
    scores
        .iter()
        .copied()
        .filter(|&s| s >= 0)
        .map(|s| (s + 5).min(100))
        .collect()
}

fn main() {
    let input = [80, 98, -10, 45];
    let output = process_scores(&input);
    println!("Processed scores: {:?}", output);
}

